CREATE TYPE "PlaybackSessionStatus" AS ENUM('ACTIVE','ENDED','EXPIRED','FAILED');CREATE TYPE "VariantHealthStatus" AS ENUM('HEALTHY','DEGRADED','UNHEALTHY','UNKNOWN');
CREATE TABLE "VariantHealth"("variantId" TEXT NOT NULL,"status" "VariantHealthStatus" NOT NULL DEFAULT 'UNKNOWN',"latencyMs" INTEGER,"consecutiveFailures" INTEGER NOT NULL DEFAULT 0,"lastSuccessAt" TIMESTAMP(3),"lastFailureAt" TIMESTAMP(3),"circuitOpenUntil" TIMESTAMP(3),"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "VariantHealth_pkey" PRIMARY KEY("variantId"));
CREATE TABLE "PlaybackSession"("id" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"userId" TEXT NOT NULL,"variantId" TEXT NOT NULL,"deviceId" TEXT NOT NULL,"status" "PlaybackSessionStatus" NOT NULL DEFAULT 'ACTIVE',"mediaTitleId" TEXT,"episodeId" TEXT,"channelId" TEXT,"expiresAt" TIMESTAMP(3) NOT NULL,"lastHeartbeatAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PlaybackSession_pkey" PRIMARY KEY("id"));
CREATE TABLE "QoeEvent"("id" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"type" TEXT NOT NULL,"value" DOUBLE PRECISION,"detail" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "QoeEvent_pkey" PRIMARY KEY("id"));CREATE UNIQUE INDEX "PlaybackSession_tokenHash_key" ON "PlaybackSession"("tokenHash");CREATE INDEX "PlaybackSession_userId_status_expiresAt_idx" ON "PlaybackSession"("userId","status","expiresAt");CREATE INDEX "PlaybackSession_variantId_status_idx" ON "PlaybackSession"("variantId","status");CREATE INDEX "QoeEvent_sessionId_createdAt_idx" ON "QoeEvent"("sessionId","createdAt");CREATE INDEX "QoeEvent_type_createdAt_idx" ON "QoeEvent"("type","createdAt");
ALTER TABLE "VariantHealth" ADD CONSTRAINT "VariantHealth_variantId_fkey" FOREIGN KEY("variantId") REFERENCES "PlaybackVariant"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "PlaybackSession" ADD CONSTRAINT "PlaybackSession_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "PlaybackSession" ADD CONSTRAINT "PlaybackSession_variantId_fkey" FOREIGN KEY("variantId") REFERENCES "PlaybackVariant"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "QoeEvent" ADD CONSTRAINT "QoeEvent_sessionId_fkey" FOREIGN KEY("sessionId") REFERENCES "PlaybackSession"("id") ON DELETE CASCADE ON UPDATE CASCADE;
